from dataclasses import dataclass
from decimal import Decimal
@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str
    def __add__(self, other):
        if self.currency != other.currency: raise ValueError('currency mismatch')
        return Money(self.amount + other.amount, self.currency)

class Order:
    def __init__(self, id, customer_id):
        self.id, self.customer_id, self.lines, self.status = id, customer_id, [], 'open'
    def add_line(self, sku, qty, price):
        if self.status != 'open': raise ValueError('order closed')
        if qty <= 0: raise ValueError('qty must be positive')
        self.lines.append(OrderLine(sku, qty, price))
    def total(self):
        return sum((l.price * l.qty for l in self.lines), Money(0, 'EUR'))

class ErpInvoiceAdapter:
    STATUS = {'01': InvoiceStatus.DRAFT, '07': InvoiceStatus.ISSUED, '99': InvoiceStatus.VOID}
    def fetch(self, invoice_id) -> Invoice:
        raw = self.erp.get('INV_HDR', invoice_id)
        return Invoice(id=raw['DOCNO'], amount=Money(Decimal(raw['NETAMT']), raw['CURR']), status=self.STATUS[raw['STS']])

class OrderRepository(Protocol):
    def get(self, order_id: str) -> Order: ...
    def save(self, order: Order) -> None: ...

class InMemoryOrders:
    def __init__(self): self._d = {}
    def get(self, oid): return self._d[oid]
    def save(self, o): self._d[o.id] = o
